// @vitest-environment happy-dom
import { afterEach, describe, expect, it } from "vitest";
import { Editor } from "@tiptap/core";
import { canRoundTrip, markdownExtensions } from "./markdown";
import {
  clearNamedBlocks,
  listNamedBlocks,
  namedBlockHtml,
  parseNamedBlockHtml,
  registerNamedBlock,
  type NamedBlockDefinition,
} from "./namedBlocks";

const note: NamedBlockDefinition = {
  id: "note",
  label: "Note",
  icon: "i-hugeicons-note",
  props: [
    { key: "title", label: "Title", type: "text" },
    { key: "body", label: "Body", type: "textarea" },
  ],
};

afterEach(() => clearNamedBlocks());

describe("namedBlocks registry", () => {
  it("registers definitions and lists them", () => {
    registerNamedBlock(note);
    expect(listNamedBlocks().map(b => b.id)).toEqual(["note"]);
  });

  it("serializes props to a stable data-orso-block wrapper", () => {
    registerNamedBlock(note);
    expect(namedBlockHtml("note", { title: "Hello", body: "World" })).toBe(
      '<aside data-orso-block="note" data-title="Hello" data-body="World"></aside>',
    );
  });

  it("parses a registered wrapper back into block id and props", () => {
    registerNamedBlock(note);
    const html = '<aside data-orso-block="note" data-title="Hello" data-body="World"></aside>';
    expect(parseNamedBlockHtml(html)).toEqual({ block: "note", props: { title: "Hello", body: "World" } });
  });

  it("rejects unregistered or malformed HTML", () => {
    registerNamedBlock(note);
    expect(parseNamedBlockHtml('<aside data-orso-block="cta" data-title="x"></aside>')).toBeNull();
    expect(parseNamedBlockHtml('<div class="box">Box</div>')).toBeNull();
  });

  it("escapes attribute values on write and unescapes on read", () => {
    registerNamedBlock(note);
    const html = namedBlockHtml("note", { title: 'Say "hi" & go', body: "a < b" });
    expect(html).toContain("Say &quot;hi&quot; &amp; go");
    expect(parseNamedBlockHtml(html)).toEqual({
      block: "note",
      props: { title: 'Say "hi" & go', body: "a < b" },
    });
  });
});

describe("namedBlocks markdown round-trip", () => {
  it("accepts a registered named block in canRoundTrip", () => {
    registerNamedBlock(note);
    const source = 'Intro\n\n<aside data-orso-block="note" data-title="Hello" data-body="World"></aside>\n';
    expect(canRoundTrip(source)).toBe(true);
  });

  it("still rejects arbitrary block HTML", () => {
    registerNamedBlock(note);
    expect(canRoundTrip('Hi\n\n<div class="box">Box</div>\n')).toBe(false);
  });

  it("parses and serializes a named block without loss", () => {
    registerNamedBlock(note);
    const md = new Editor({ extensions: markdownExtensions() }).markdown!;
    const source = '<aside data-orso-block="note" data-title="Hello" data-body="World"></aside>';
    const doc = md.parse(source);
    expect(doc.content?.[0]).toMatchObject({
      type: "namedBlock",
      attrs: { block: "note", props: { title: "Hello", body: "World" } },
    });
    expect(md.serialize(doc).trim()).toBe(source);
  });
});

/**
 * Extensible named HTML blocks for the rich Markdown editor.
 *
 * Register a definition (`id`, prop schema, label) and the editor stores it as a
 * `namedBlock` atom. Markdown round-trips through a stable
 * `<aside data-orso-block="…">` wrapper; unknown HTML still fails `canRoundTrip`.
 */

export type NamedBlockPropType = "text" | "textarea" | "url";

export interface NamedBlockProp {
  key: string;
  label: string;
  type: NamedBlockPropType;
  required?: boolean;
}

export interface NamedBlockDefinition {
  id: string;
  label: string;
  icon?: string;
  props: NamedBlockProp[];
}

export type NamedBlockAttrs = { block: string; props: Record<string, string> };

const registry = new Map<string, NamedBlockDefinition>();

/** Drop every registered definition (tests). */
export function clearNamedBlocks(): void {
  registry.clear();
}

/** Register or replace a named block definition. */
export function registerNamedBlock(definition: NamedBlockDefinition): void {
  if (!definition.id) throw new Error("named block id is required");
  registry.set(definition.id, definition);
}

export function getNamedBlock(id: string): NamedBlockDefinition | undefined {
  return registry.get(id);
}

export function listNamedBlocks(): NamedBlockDefinition[] {
  return [...registry.values()];
}

function kebab(key: string): string {
  return key.replace(/[A-Z]/g, m => `-${m.toLowerCase()}`);
}

function escapeAttr(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

/** Stable HTML written into Markdown for a registered block. */
export function namedBlockHtml(block: string, props: Record<string, string>): string {
  const def = registry.get(block);
  if (!def) return "";
  const attrs = [`data-orso-block="${escapeAttr(block)}"`];
  for (const prop of def.props) {
    attrs.push(`data-${kebab(prop.key)}="${escapeAttr(props[prop.key] ?? "")}"`);
  }
  return `<aside ${attrs.join(" ")}></aside>`;
}

/**
 * Parse a block-level HTML snippet into named-block attrs when it matches a
 * registered `data-orso-block` wrapper; otherwise null.
 */
export function parseNamedBlockHtml(html: string): NamedBlockAttrs | null {
  const trimmed = html.trim();
  if (!trimmed || typeof DOMParser === "undefined") return null;
  const doc = new DOMParser().parseFromString(trimmed, "text/html");
  const el = doc.body.firstElementChild;
  if (!el || el !== doc.body.lastElementChild) return null;
  const id = el.getAttribute("data-orso-block");
  if (!id) return null;
  const def = registry.get(id);
  if (!def) return null;
  const props: Record<string, string> = {};
  for (const prop of def.props) {
    props[prop.key] = el.getAttribute(`data-${kebab(prop.key)}`) ?? "";
  }
  return { block: id, props };
}

import { mergeAttributes, Node } from "@tiptap/core";
import { VueNodeViewRenderer } from "@tiptap/vue-3";
import NamedBlockView from "./NamedBlockView.vue";
import { namedBlockHtml, parseNamedBlockHtml } from "./namedBlocks";

/**
 * TipTap atom for registry-backed HTML sections. Markdown uses marked's block
 * `html` tokens; only wrappers that `parseNamedBlockHtml` accepts become nodes.
 */
export const NamedBlock = Node.create({
  name: "namedBlock",
  group: "block",
  atom: true,
  selectable: true,
  draggable: true,

  addAttributes() {
    return {
      block: {
        default: "",
        parseHTML: (el: HTMLElement) => el.getAttribute("data-orso-block") ?? "",
        renderHTML: (attrs: Record<string, unknown>) => ({ "data-orso-block": attrs.block }),
      },
      props: {
        default: {},
        parseHTML: (el: HTMLElement) => {
          try {
            return JSON.parse(el.getAttribute("data-props") || "{}") as Record<string, string>;
          } catch {
            return {};
          }
        },
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-props": JSON.stringify(attrs.props ?? {}),
        }),
      },
    };
  },

  parseHTML() {
    return [{ tag: "div[data-named-block]" }];
  },

  renderHTML({ HTMLAttributes }) {
    // Safe editor wrapper only — never emit author HTML into the CMS origin.
    return ["div", mergeAttributes(HTMLAttributes, { "data-named-block": "" })];
  },

  markdownTokenName: "html",

  parseMarkdown(token, h) {
    if (!token.block) return [];
    const parsed = parseNamedBlockHtml(String(token.text ?? token.raw ?? ""));
    if (!parsed) return [];
    return h.createNode("namedBlock", { block: parsed.block, props: parsed.props });
  },

  renderMarkdown(node) {
    const block = String(node.attrs?.block ?? "");
    const props = (node.attrs?.props ?? {}) as Record<string, string>;
    return namedBlockHtml(block, props);
  },

  addNodeView() {
    return VueNodeViewRenderer(NamedBlockView);
  },
});

